import { TextSelection } from './../../pm/state.js';

import type { RawCommands } from '../types.js';

declare module './../../core' {
  interface Commands<ReturnType> {
    blur: {
      /**
       * Removes focus from the editor.
       * @example editor.commands.blur()
       */
      blur: () => ReturnType;
    };
  }
}

export const blur: RawCommands['blur'] =
  () =>
  ({ editor, view, tr, dispatch }) => {
    // PM keeps the DOM in sync with its selection state: a non-collapsed
    // TextSelection renders as a native highlight, a NodeSelection adds the
    // `selectednode` decoration, and a CellSelection paints cell backgrounds —
    // all independent of DOM focus. Just blurring view.dom (and clearing the
    // native range) isn't enough: PM resyncs on the next view update and the
    // visual selection returns. Collapse the selection in state first so the
    // resync has nothing visible to render.
    //
    // Read from `tr.selection` rather than `editor.state.selection` so the
    // check sees prior chained mutations — e.g. `chain().selectAll().blur()`
    // collapses the AllSelection that selectAll just put on `tr`, not the
    // stale pre-chain editor state.
    if (dispatch && !tr.selection.empty) {
      const { $anchor } = tr.selection;
      tr.setSelection(TextSelection.between($anchor, $anchor));
    }

    requestAnimationFrame(() => {
      if (editor.isDestroyed) {
        return;
      }

      // Check ownership of the native selection BEFORE blurring — the act of
      // blurring can drop the range on some platforms, and we need to know
      // whether the range was ours to clean up.
      const nativeSelection = window?.getSelection();
      const anchorNode = nativeSelection?.anchorNode;
      const ownsNativeRange = !!anchorNode && view.dom.contains(anchorNode);

      (view.dom as HTMLElement).blur();

      // Browsers should remove the caret on blur but safari does not.
      // See: https://github.com/ueberdosis/tiptap/issues/2405
      // `removeAllRanges` is window-global, so in multi-editor hosts (e.g.
      // wixel switching docs) calling it unconditionally would wipe a sibling
      // editor's caret. Only clear when the native range was ours.
      if (ownsNativeRange) {
        nativeSelection?.removeAllRanges();
      }
    });

    return true;
  };
