import type { ForwardedRef, HTMLProps, LegacyRef, MutableRefObject, ReactPortal } from 'react';
import React, { forwardRef } from 'react';
import ReactDOM from 'react-dom';
import { useSyncExternalStore } from 'use-sync-external-store/shim';

// Vendored from @tiptap/react v2.8.0
import type { Editor } from './../core/index.js';

import type { ContentComponent, EditorWithContentComponent } from './editor-types.js';
import type { ReactRenderer } from './react-renderer.js';

const mergeRefs = <T extends HTMLDivElement>(
  ...refs: Array<MutableRefObject<T> | LegacyRef<T> | undefined>
): ((node: T) => void) => {
  return (node: T) => {
    refs.forEach(ref => {
      if (typeof ref === 'function') {
        ref(node);
      } else if (ref) {
        (ref as MutableRefObject<T | null>).current = node;
      }
    });
  };
};

/**
 * This component renders all of the editor's node views.
 */
const Portals: React.FC<{ contentComponent: ContentComponent }> = ({ contentComponent }) => {
  // For performance reasons, we render the node view portals on state changes only
  const renderers = useSyncExternalStore(
    contentComponent.subscribe,
    contentComponent.getSnapshot,
    contentComponent.getServerSnapshot
  );

  // This allows us to directly render the portals without any additional wrapper
  return <>{Object.values(renderers)}</>;
};

export type EditorContentProps = HTMLProps<HTMLDivElement> & {
  editor: Editor | null;
  innerRef?: ForwardedRef<HTMLDivElement | null>;
  // Preserve the editor's DOM across a transient unmount + remount instead of
  // tearing it down (the same editor instance is reused on remount).
  preserveDomOnUnmount?: boolean;
};

const getInstance = (): ContentComponent => {
  const subscribers = new Set<() => void>();
  let renderers: Record<string, ReactPortal> = {};

  return {
    /**
     * Subscribe to the editor instance's changes.
     */
    subscribe(callback: () => void) {
      subscribers.add(callback);
      return () => {
        subscribers.delete(callback);
      };
    },
    getSnapshot() {
      return renderers;
    },
    getServerSnapshot() {
      return renderers;
    },
    /**
     * Adds a new NodeView Renderer to the editor.
     */
    setRenderer(id: string, renderer: ReactRenderer) {
      renderers = {
        ...renderers,
        [id]: ReactDOM.createPortal(renderer.reactElement, renderer.element, id),
      };

      subscribers.forEach(subscriber => subscriber());
    },
    /**
     * Removes a NodeView Renderer from the editor.
     */
    removeRenderer(id: string) {
      const nextRenderers = { ...renderers };

      delete nextRenderers[id];
      renderers = nextRenderers;
      subscribers.forEach(subscriber => subscriber());
    },
  };
};

type PureEditorContentState = { hasContentComponentInitialized: boolean };

export class PureEditorContent extends React.Component<EditorContentProps, PureEditorContentState> {
  editorContentRef: React.RefObject<HTMLDivElement>;

  initialized: boolean;

  unsubscribeToContentComponent?: () => void;

  constructor(props: EditorContentProps) {
    super(props);
    this.editorContentRef = React.createRef();
    this.initialized = false;

    this.state = {
      hasContentComponentInitialized: Boolean(
        (props.editor as EditorWithContentComponent | null)?.contentComponent
      ),
    };
  }

  componentDidMount(): void {
    this.init();
  }

  componentDidUpdate(): void {
    this.init();
  }

  init(): void {
    const editor = this.props.editor as EditorWithContentComponent | null;

    if (!editor || editor.isDestroyed || !editor.options.element) {
      return;
    }

    const element = this.editorContentRef.current;

    if (!element) {
      return;
    }

    if (editor.contentComponent) {
      // A preserved unmount left the editor's DOM in another container — adopt it here.
      if (
        this.props.preserveDomOnUnmount &&
        editor.options.element !== element &&
        editor.options.element.firstChild
      ) {
        element.append(...editor.options.element.childNodes);
        editor.setOptions({ element });
      }
      return;
    }

    element.append(...editor.options.element.childNodes);

    editor.setOptions({
      element,
    });

    editor.contentComponent = getInstance();

    // Has the content component been initialized?
    if (!this.state.hasContentComponentInitialized) {
      // Subscribe to the content component
      this.unsubscribeToContentComponent = editor.contentComponent.subscribe(() => {
        this.setState(prevState => {
          if (!prevState.hasContentComponentInitialized) {
            return {
              hasContentComponentInitialized: true,
            };
          }
          return prevState;
        });

        // Unsubscribe to previous content component
        if (this.unsubscribeToContentComponent) {
          this.unsubscribeToContentComponent();
        }
      });
    }

    editor.createNodeViews();

    this.initialized = true;
  }

  componentWillUnmount(): void {
    const editor = this.props.editor as EditorWithContentComponent | null;

    if (!editor) {
      return;
    }

    const el = editor.options.element;

    // Still connected: this is a transient unmount and the same editor will be
    // remounted. Leave everything intact so init() can re-adopt it.
    if (this.props.preserveDomOnUnmount && el.isConnected) {
      return;
    }

    this.initialized = false;
    if (!editor.isDestroyed) {
      editor.view.setProps({ nodeViews: {} });
    }
    if (this.unsubscribeToContentComponent) {
      this.unsubscribeToContentComponent();
    }
    editor.contentComponent = null;

    if (!el.firstChild) {
      return;
    }

    const holder = document.createElement('div');
    holder.append(...el.childNodes);
    editor.setOptions({ element: holder });
  }

  render(): React.ReactNode {
    const { editor, innerRef, preserveDomOnUnmount, ...rest } = this.props;
    const editorCast = editor as EditorWithContentComponent | null;

    return (
      <>
        <div ref={mergeRefs(innerRef, this.editorContentRef)} {...rest} />
        {editorCast?.contentComponent && <Portals contentComponent={editorCast.contentComponent} />}
      </>
    );
  }
}

// EditorContent should be re-created whenever the Editor instance changes
const EditorContentWithKey = forwardRef<HTMLDivElement, EditorContentProps>(
  (props: Omit<EditorContentProps, 'innerRef'>, ref) => {
    const key = React.useMemo(() => {
      return Math.floor(Math.random() * 0xffffffff).toString();
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [props.editor]);

    // Can't use JSX here because it conflicts with the type definition of Vue's JSX, so use createElement
    return React.createElement(PureEditorContent, {
      key,
      innerRef: ref,
      ...props,
    });
  }
);

EditorContentWithKey.displayName = 'EditorContentWithKey';

export const EditorContent = React.memo(EditorContentWithKey);
