import type { Node as ProseMirrorNode } from './../pm/model.js';

import type { NodeWithPos, Predicate, Range } from '../types.js';

export const findChildrenInRange = (
  node: ProseMirrorNode,
  range: Range,
  predicate: Predicate
): NodeWithPos[] => {
  const nodesWithPos: NodeWithPos[] = [];

  node.nodesBetween(range.from, range.to, (child, pos) => {
    if (predicate(child)) {
      nodesWithPos.push({
        node: child,
        pos,
      });
    }
  });

  return nodesWithPos;
};
