import { Plugin, PluginKey } from './../../pm/state.js';

import { Extension } from '../extension.js';

export const Editable = Extension.create({
  name: 'editable',

  addProseMirrorPlugins() {
    return [
      new Plugin({
        key: new PluginKey('editable'),
        props: {
          editable: () => this.editor.options.editable,
        },
      }),
    ];
  },
});
