import { TextSelection } from './../../pm/state.js';

import type { Range, RawCommands } from '../types.js';
import { minMax } from '../utilities/min-max.js';

declare module './../../core' {
  interface Commands<ReturnType> {
    setTextSelection: {
      /**
       * Creates a TextSelection.
       * @param position The position of the selection.
       * @example editor.commands.setTextSelection(10)
       */
      setTextSelection: (position: number | Range) => ReturnType;
    };
  }
}

export const setTextSelection: RawCommands['setTextSelection'] =
  position =>
  ({ tr, dispatch }) => {
    if (dispatch) {
      const { doc } = tr;
      const { from, to } =
        typeof position === 'number' ? { from: position, to: position } : position;
      const minPos = TextSelection.atStart(doc).from;
      const maxPos = TextSelection.atEnd(doc).to;
      const resolvedFrom = minMax(from, minPos, maxPos);
      const resolvedEnd = minMax(to, minPos, maxPos);
      const selection = TextSelection.create(doc, resolvedFrom, resolvedEnd);

      tr.setSelection(selection);
    }

    return true;
  };
